import sys
sys.path.insert(0,'/opt/tools')
import casa_tool
s=casa_tool.Session('/app/instance.npz')
for c in s.camera_views:
 try:
  im=s.render(c)
  from PIL import Image
  Image.fromarray(im).save('/app/output/'+c+'.png')
  print(c,im.shape)
 except Exception as e: print('render failed',c,repr(e))
m,d=s.model,s.data
for j in range(m.njnt):
 n=m.joint(j).name
 if 'microjoint' in n:
  print('hinge id',j,'body',m.body(m.jnt_bodyid[j]).name,'anchor local',m.jnt_pos[j],'axis',m.jnt_axis[j])
for i in range(m.ngeom):
 n=m.geom(i).name
 if 'microwave_front' in n:
  print(i,n,'body',m.body(m.geom_bodyid[i]).name,'type',m.geom_type[i],'size',m.geom_size[i], 'pos',d.geom_xpos[i])
for i in range(m.nsite):
 n=m.site(i).name
 if 'microwave_front' in n:
  print('site',n,'pos',d.site_xpos[i], 'quat?',d.site_xmat[i].reshape(3,3))
print('eef quat', d.site_xmat[s.env.robots[0].eef_site_id['right']].reshape(3,3))
print('door qpos',d.qpos[m.joint('microwave_front_group_microjoint').qposadr[0]])
